// Package testpki writes, for tests, the directories a sub CA of another PKI issues: laid out as
// a bundle, its certificates naming a CRL, which a bundle generated by rat-tool never does.
package testpki

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/pem"
	"math/big"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/hekmon/rat/mtls"
)

// SubCABundle writes the directories of tenant as a sub CA of another PKI issues them, laid out as
// a bundle: the server, and clients alice and bob, their certificates naming crlURL as their CRL
// distribution point, and carol, whose certificate names none, refusing such a server. It
// returns the directory, and a function returning a CRL of the CA in DER, stale if asked,
// revoking the certificates of the names given ("server" for the server).
func SubCABundle(t testing.TB, tenant, crlURL string) (string, func(stale bool, revoked ...string) []byte) {
	t.Helper()
	now := time.Now()
	caKey, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	caTemplate := &x509.Certificate{SerialNumber: big.NewInt(1), Subject: pkix.Name{CommonName: tenant},
		NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), IsCA: true, BasicConstraintsValid: true,
		KeyUsage: x509.KeyUsageCertSign | x509.KeyUsageCRLSign, MaxPathLenZero: true}
	caDER, err := x509.CreateCertificate(rand.Reader, caTemplate, caTemplate, &caKey.PublicKey, caKey)
	if err != nil {
		t.Fatal(err)
	}
	ca, err := x509.ParseCertificate(caDER)
	if err != nil {
		t.Fatal(err)
	}
	bundle := filepath.Join(t.TempDir(), "bundle")
	serials := map[string]*big.Int{}
	for i, side := range []struct {
		name, dir string
		usage     x509.ExtKeyUsage
		crl       bool
	}{
		{"server", mtls.ServerDir(bundle), x509.ExtKeyUsageServerAuth, true},
		{"alice", mtls.ClientDir(bundle, "alice"), x509.ExtKeyUsageClientAuth, true},
		{"bob", mtls.ClientDir(bundle, "bob"), x509.ExtKeyUsageClientAuth, true},
		{"carol", mtls.ClientDir(bundle, "carol"), x509.ExtKeyUsageClientAuth, false},
	} {
		key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
		if err != nil {
			t.Fatal(err)
		}
		name, role := side.name, "client"
		if side.usage == x509.ExtKeyUsageServerAuth {
			name, role = tenant, "server"
		}
		template := &x509.Certificate{SerialNumber: big.NewInt(int64(i + 2)), Subject: pkix.Name{CommonName: name},
			NotBefore: now.Add(-time.Hour), NotAfter: now.Add(time.Hour), KeyUsage: x509.KeyUsageDigitalSignature,
			ExtKeyUsage: []x509.ExtKeyUsage{side.usage}}
		if side.crl {
			template.CRLDistributionPoints = []string{crlURL}
		}
		certDER, err := x509.CreateCertificate(rand.Reader, template, ca, &key.PublicKey, caKey)
		if err != nil {
			t.Fatal(err)
		}
		keyDER, err := x509.MarshalPKCS8PrivateKey(key)
		if err != nil {
			t.Fatal(err)
		}
		if err = os.MkdirAll(side.dir, 0o700); err != nil {
			t.Fatal(err)
		}
		for file, block := range map[string]*pem.Block{
			"ca.crt":      {Type: "CERTIFICATE", Bytes: caDER},
			role + ".crt": {Type: "CERTIFICATE", Bytes: certDER},
			role + ".key": {Type: "PRIVATE KEY", Bytes: keyDER},
		} {
			if err = os.WriteFile(filepath.Join(side.dir, file), pem.EncodeToMemory(block), 0o600); err != nil {
				t.Fatal(err)
			}
		}
		serials[side.name] = template.SerialNumber
	}
	crl := func(stale bool, revoked ...string) []byte {
		thisUpdate := now.Add(-time.Hour)
		if stale {
			thisUpdate = now.Add(-3 * time.Hour)
		}
		var entries []x509.RevocationListEntry
		for _, name := range revoked {
			entries = append(entries, x509.RevocationListEntry{SerialNumber: serials[name], RevocationTime: thisUpdate})
		}
		der, err := x509.CreateRevocationList(rand.Reader, &x509.RevocationList{Number: big.NewInt(1),
			ThisUpdate: thisUpdate, NextUpdate: thisUpdate.Add(2 * time.Hour), RevokedCertificateEntries: entries}, ca, caKey)
		if err != nil {
			t.Fatal(err)
		}
		return der
	}
	return bundle, crl
}
